{
  "operations": [
    {
      "op": "set_weight",
      "component": "node_score",
      "feature": "dependency_latency",
      "weight": 0.0
    }
  ],
  "rationale": "The migration budget constraint is violated because services are placed on different satellites than their previous locations. The node_score currently penalizes dependency_latency, which may favor placing services on the same satellite as their dependencies, but the migration penalty is absent. Setting dependency_latency weight to 0 removes its influence, potentially allowing the migration penalty to be added later to discourage migrations and satisfy the budget.",
  "version": "1.0"
}
